arguments.command:
cd /tmp/vally-eval-trial-AjS0vG && cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public sealed record CalculatePayableTotalQuery(string CustomerTier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalQuery query) => query.OrderSubtotal;
}
E
mkdir -p tests/CheckoutPricing.UnitTests/Application && cat > tests/CheckoutPricing.UnitTests/Application/LoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Application;

public sealed class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void S1_GoldCustomerReceivesTheApprovedDiscount()
    {
        var handler = new CalculatePayableTotalHandler();

        var payableTotal = handler.Handle(new CalculatePayableTotalQuery("Gold", 100.00m));

        Assert.Equal(95.00m, payableTotal);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --verbosity quiet 2>&1 | grep -v "^$" | head -25

